-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_COMMON_GEO
--   anchor      : HUB_LOCATION
--   grain       : SCD2 (data_7.js sats[].hist)
--   child key   : (none declared)
--   feeders     : 2 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 3 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_LOCATION_BK__K5)) as HUB_LOCATION_HK,
        null::varchar as REGION_NAME,
        ZONE as ZONE_CODE,
        RURAL_NON_RURAL as URBAN_RURAL_CLASSIFICATION,
        'MAXI_HLTH_UWR_VW_DATA_BASIC_DETAIL_ATTRIBUTE_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_bd_apv') }}
    where HUB_LOCATION_K5__EMIT
    union all
    select
        md5(upper(HUB_LOCATION_BK__K2)) as HUB_LOCATION_HK,
        CLIENT_GEOGRAPHY as REGION_NAME,
        null::varchar as ZONE_CODE,
        null::varchar as URBAN_RURAL_CLASSIFICATION,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_PARTY_PARTY_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_ppd_pv') }}
    where HUB_LOCATION_K2__EMIT
)), hashed as (select *,
        case when REGION_NAME is not null or ZONE_CODE is not null or URBAN_RURAL_CLASSIFICATION is not null
             then md5(upper(coalesce(REGION_NAME::varchar,'') || '||' || coalesce(ZONE_CODE::varchar,'') || '||' || coalesce(URBAN_RURAL_CLASSIFICATION::varchar,'')))
        end as SAT_COMMON_GEO_HASHDIFF
    from feeders)

select * from hashed
where HUB_LOCATION_HK is not null
  and SAT_COMMON_GEO_HASHDIFF is not null
